files.content:
/* Palette: #1a1a2e (bg), #16213e (card), #e94560 (accent), #f5f5f5 (text), #0f3460 (border) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: #1a1a2e;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  padding: 16px;
  color: #f5f5f5;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  padding: 32px 28px;
  width: 100%;
  max-width: 420px;
  box-shadow: 8px 8px 0 #0f3460;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 4px;
  letter-spacing: 1px;
  color: #e94560;
  text-shadow: 2px 2px 0 #0f3460;
}

.subtitle {
  text-align: center;
  margin-bottom: 24px;
  color: #8899aa;
  font-size: 0.9rem;
}

.field {
  margin-bottom: 18px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: bold;
  letter-spacing: 0.5px;
  color: #e94560;
}

input,
select {
  width: 100%;
  padding: 12px 14px;
  font-family: inherit;
  font-size: 1rem;
  background: #0f3460;
  color: #f5f5f5;
  border: 3px solid #0f3460;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input::placeholder {
  color: #6a7a8a;
}

input:hover,
select:hover {
  border-color: #e94560;
}

input:focus,
select:focus {
  border-color: #e94560;
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

button {
  width: 100%;
  padding: 14px;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  letter-spacing: 1px;
  text-transform: uppercase;
  background: #e94560;
  color: #f5f5f5;
  border: 3px solid #e94560;
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 #0f3460;
  transition: transform 0.1s, box-shadow 0.1s, background 0.15s;
}

button:hover {
  background: #ff5a75;
  border-color: #ff5a75;
}

button:focus-visible {
  outline: 3px solid #f5f5f5;
  outline-offset: 2px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #0f3460;
}

.result-field {
  margin-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 16px;
  background: #0f3460;
  border: 3px solid #0f3460;
}

.result-label {
  font-weight: bold;
  color: #e94560;
  letter-spacing: 0.5px;
}

#result {
  font-size: 1.4rem;
  font-weight: bold;
  color: #f5f5f5;
  min-width: 4ch;
  text-align: right;
}

.formulas {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 2px dashed #0f3460;
  font-size: 0.85rem;
  color: #8899aa;
  line-height: 1.8;
}

.formulas strong {
  color: #e94560;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 18px;
  }
  h1 {
    font-size: 1.3rem;
  }
}

document.addEventListener('DOMContentLoaded', function () {
  var tempInput = document.getElementById('temperature');
  var directionSelect = document.getElementById('direction');
  var convertBtn = document.getElementById('convert');
  var resultOutput = document.getElementById('result');

  function convert() {
    var raw = tempInput.value.trim();
    var num = Number(raw);

    if (raw === '' || !isFinite(num)) {
      resultOutput.textContent = 'Error';
      return;
    }

    var result;
    if (directionSelect.value === 'c-to-f') {
      result = num * 9 / 5 + 32;
    } else {
      result = (num - 32) * 5 / 9;
    }

    resultOutput.textContent = result.toFixed(2);
  }

  convertBtn.addEventListener('click', convert);

  tempInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      convert();
    }
  });
});
